-- Employees master table (mirrors EMPREC copybook)
CREATE TABLE IF NOT EXISTS employees (
    emp_id      INTEGER         NOT NULL,
    emp_name    VARCHAR(20)     NOT NULL,
    emp_salary  NUMERIC(9, 2)   NOT NULL,
    CONSTRAINT pk_employees PRIMARY KEY (emp_id)
);

-- Tax results – written once per run, keyed by run_id + emp_id
CREATE TABLE IF NOT EXISTS tax_results (
    id          BIGSERIAL       PRIMARY KEY,
    run_id      UUID            NOT NULL,
    emp_id      INTEGER         NOT NULL,
    emp_name    VARCHAR(20)     NOT NULL,
    gross_pay   NUMERIC(9, 2)   NOT NULL,
    tax_amount  NUMERIC(9, 2)   NOT NULL,
    net_pay     NUMERIC(9, 2)   NOT NULL,
    eff_rate    NUMERIC(5, 1)   NOT NULL,
    created_at  TIMESTAMP       NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_tax_results_run_id ON tax_results(run_id);

