package com.example.taxcalc.domain;

import jakarta.persistence.*;
import jakarta.validation.constraints.*;
import lombok.*;

import java.math.BigDecimal;

/**
 * Mirrors the EMPREC copybook fields:
 *   EMP-ID      PIC 9(05)
 *   EMP-NAME    PIC X(20)
 *   EMP-SALARY  PIC 9(07)V99
 */
@Entity
@Table(name = "employees")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@ToString
public class Employee {

    @Id
    @Column(name = "emp_id")
    private Integer empId;

    @NotBlank
    @Size(max = 20)
    @Column(name = "emp_name", length = 20, nullable = false)
    private String empName;

    @NotNull
    @DecimalMin(value = "0.00")
    @Column(name = "emp_salary", precision = 9, scale = 2, nullable = false)
    private BigDecimal empSalary;
}

