package com.example.taxcalc.domain;

import jakarta.persistence.*;
import lombok.*;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.UUID;

/**
 * Persisted tax computation result for a single employee within one batch run.
 */
@Entity
@Table(name = "tax_results")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
@ToString
public class TaxResult {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "run_id", nullable = false)
    private UUID runId;

    @Column(name = "emp_id", nullable = false)
    private Integer empId;

    @Column(name = "emp_name", length = 20, nullable = false)
    private String empName;

    @Column(name = "gross_pay", precision = 9, scale = 2, nullable = false)
    private BigDecimal grossPay;

    @Column(name = "tax_amount", precision = 9, scale = 2, nullable = false)
    private BigDecimal taxAmount;

    @Column(name = "net_pay", precision = 9, scale = 2, nullable = false)
    private BigDecimal netPay;

    /** Effective tax rate as a percentage, e.g. 15.0 means 15.0% */
    @Column(name = "eff_rate", precision = 5, scale = 1, nullable = false)
    private BigDecimal effRate;

    @Column(name = "created_at", nullable = false)
    private LocalDateTime createdAt;

    @PrePersist
    void prePersist() {
        if (createdAt == null) {
            createdAt = LocalDateTime.now();
        }
    }
}

