@Repository
public interface TaxResultRepository extends JpaRepository<TaxResult, Long> {

    List<TaxResult> findByRunIdOrderByEmpIdAsc(UUID runId);

    @Query("SELECT COALESCE(SUM(t.taxAmount), 0) FROM TaxResult t WHERE t.runId = :runId")
