package com.example.taxcalc.service;

import com.example.taxcalc.domain.Employee;
import com.example.taxcalc.domain.TaxResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.util.UUID;

/**
 * Encapsulates the CALC-TAX paragraph logic from TAXCALC.cbl.
 *
 * Progressive brackets (identical to COBOL EVALUATE):
 *   0 – 30,000        :  0 %
 *   30,001 – 60,000   : 10 % on amount above 30,000
 *   60,001 – 90,000   : 3,000 + 20 % on amount above 60,000
 *   Above 90,000      : 9,000 + 30 % on amount above 90,000
 *
 * Rounding: HALF_UP to 2 decimal places (mirrors COBOL ROUNDED).
 */
@Slf4j
@Service
public class TaxCalculationService {

    private static final BigDecimal BRACKET_1 = new BigDecimal("30000");
    private static final BigDecimal BRACKET_2 = new BigDecimal("60000");
    private static final BigDecimal BRACKET_3 = new BigDecimal("90000");

    private static final BigDecimal RATE_10 = new BigDecimal("0.10");
    private static final BigDecimal RATE_20 = new BigDecimal("0.20");
    private static final BigDecimal RATE_30 = new BigDecimal("0.30");

    private static final BigDecimal TAX_AT_BRACKET_2 = new BigDecimal("3000");  // tax accumulated up to 60,000
    private static final BigDecimal TAX_AT_BRACKET_3 = new BigDecimal("9000");  // tax accumulated up to 90,000

    private static final BigDecimal ONE_HUNDRED = new BigDecimal("100");
    private static final int        SCALE = 2;
    private static final RoundingMode ROUNDING = RoundingMode.HALF_UP;

    /**
     * Computes tax for one employee and returns a fully populated {@link TaxResult}.
     *
     * @param employee the employee record read from the database
     * @param runId    batch run identifier
     * @return populated TaxResult (not yet persisted)
     */
    public TaxResult calculate(Employee employee, UUID runId) {
        BigDecimal salary = employee.getEmpSalary();

        // ── CALC-TAX EVALUATE TRUE ──────────────────────────────────────
        BigDecimal tax;
        if (salary.compareTo(BRACKET_1) <= 0) {
            // WHEN EMP-SALARY <= 30000 → MOVE 0 TO WS-TAX
            tax = BigDecimal.ZERO;
        } else if (salary.compareTo(BRACKET_2) <= 0) {
            // WHEN EMP-SALARY <= 60000
            // COMPUTE WS-TAX ROUNDED = (EMP-SALARY - 30000) * 0.10
            tax = salary.subtract(BRACKET_1)
                        .multiply(RATE_10)
                        .setScale(SCALE, ROUNDING);
        } else if (salary.compareTo(BRACKET_3) <= 0) {
            // WHEN EMP-SALARY <= 90000
            // COMPUTE WS-TAX ROUNDED = 3000 + (EMP-SALARY - 60000) * 0.20
            tax = TAX_AT_BRACKET_2
                        .add(salary.subtract(BRACKET_2).multiply(RATE_20))
                        .setScale(SCALE, ROUNDING);
        } else {
            // WHEN OTHER
            // COMPUTE WS-TAX ROUNDED = 9000 + (EMP-SALARY - 90000) * 0.30
            tax = TAX_AT_BRACKET_3
                        .add(salary.subtract(BRACKET_3).multiply(RATE_30))
                        .setScale(SCALE, ROUNDING);
        }

        // COMPUTE WS-NET = EMP-SALARY - WS-TAX
        BigDecimal net = salary.subtract(tax).setScale(SCALE, ROUNDING);

        // COMPUTE WS-RATE ROUNDED = WS-TAX * 100 / EMP-SALARY
        // Guard against division by zero (salary == 0 → rate = 0)
        BigDecimal effRate;
        if (salary.compareTo(BigDecimal.ZERO) == 0) {
            effRate = BigDecimal.ZERO.setScale(1, ROUNDING);
        } else {
            effRate = tax.multiply(ONE_HUNDRED)
                        .divide(salary, 1, ROUNDING);
        }

        log.debug("EMP={} SALARY={} TAX={} NET={} RATE={}%",
                  employee.getEmpId(), salary, tax, net, effRate);

        return TaxResult.builder()
                .runId(runId)
                .empId(employee.getEmpId())
                .empName(employee.getEmpName())
                .grossPay(salary)
                .taxAmount(tax)
                .netPay(net)
                .effRate(effRate)
                .build();
    }
}

