package com.example.taxcalc.service;

import com.example.taxcalc.domain.TaxResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.io.BufferedWriter;
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.text.NumberFormat;
import java.util.List;
import java.util.Locale;

/**
 * Generates the fixed-width tax report to a flat file.
 *
 * Mirrors the COBOL report layout:
 *   Col  1-5   : Employee ID      (PIC 9(05))
 *   Col  6-7   : spaces
 *   Col  8-27  : Employee Name    (PIC X(20))
 *   Col 28     : space
 *   Col 29-39  : Gross Pay        (Z,ZZZ,ZZ9.99  – right-justified, 11 chars)
 *   Col 40-41  : spaces
 *   Col 42-52  : Tax Amount       (Z,ZZZ,ZZ9.99  – 11 chars)
 *   Col 53-54  : spaces
 *   Col 55-65  : Net Pay          (Z,ZZZ,ZZ9.99  – 11 chars)
 *   Col 66-67  : spaces
 *   Col 68-71  : Eff Rate         (Z9.9          –  4 chars)
 *   Total line length: 80 chars (padded with spaces)
 */
@Slf4j
@Service
public class ReportService {

    @Value("${taxcalc.report.output-path:data/output/tax.rpt}")
    private String reportOutputPath;

    // ── Header / separator constants (mirrors COBOL Working-Storage) ─────
    private static final String TITLE        = "ANNUAL INCOME TAX REPORT";
    private static final String SEP_LINE     = "-".repeat(80);
    private static final String HDR_1        =
            padRight("ID", 7) +
            padRight("NAME", 21) +
            padLeft("GROSS PAY", 14) +
            padLeft("TAX", 14) +
            padLeft("NET PAY", 14) +
            padRight("EFF%", 6);
    private static final String TOTAL_LABEL  = padRight("TOTAL TAX WITHHELD:", 42);

    // ── Number formatters ────────────────────────────────────────────────
    // Z,ZZZ,ZZ9.99 → 11-char field; leading zeros suppressed except units digit
    private static final NumberFormat MONEY_FMT;
    // ZZZ,ZZZ,ZZ9.99 → 14-char field (total line)
    private static final NumberFormat TOTAL_FMT;
    // Z9.9 → 4-char field
    private static final NumberFormat RATE_FMT;

    static {
        MONEY_FMT = NumberFormat.getNumberInstance(Locale.US);
        MONEY_FMT.setMinimumFractionDigits(2);
        MONEY_FMT.setMaximumFractionDigits(2);
        MONEY_FMT.setGroupingUsed(true);

        TOTAL_FMT = NumberFormat.getNumberInstance(Locale.US);
        TOTAL_FMT.setMinimumFractionDigits(2);
        TOTAL_FMT.setMaximumFractionDigits(2);
        TOTAL_FMT.setGroupingUsed(true);

        RATE_FMT = NumberFormat.getNumberInstance(Locale.US);
        RATE_FMT.setMinimumFractionDigits(1);
        RATE_FMT.setMaximumFractionDigits(1);
        RATE_FMT.setGroupingUsed(false);
    }

    /**
     * Writes the complete flat-file report.
     *
     * @param results   ordered list of per-employee tax results
     * @param totalTax  sum of all taxAmount values
     */
    public void writeReport(List<TaxResult> results, BigDecimal totalTax) throws IOException {
        Path outputPath = Paths.get(reportOutputPath);
        Files.createDirectories(outputPath.getParent());

        try (BufferedWriter writer = Files.newBufferedWriter(outputPath, StandardCharsets.UTF_8)) {

            // ── MAIN-PARA header block ──────────────────────────────────
            writeLine(writer, TITLE);
            writeLine(writer, SEP_LINE);
            writeLine(writer, HDR_1);
            writeLine(writer, SEP_LINE);

            // ── Detail lines (one per employee) ────────────────────────
            for (TaxResult r : results) {
                writeLine(writer, formatDetailLine(r));
            }

            // ── Trailer block ───────────────────────────────────────────
            writeLine(writer, SEP_LINE);
            writeLine(writer, formatTrailerLine(totalTax));
        }

        log.info("TAXCALC: TAX REPORT WRITTEN to {}", outputPath.toAbsolutePath());
    }

    // ── Private helpers ──────────────────────────────────────────────────

    /**
     * Formats one DTL-LINE (80 chars).
     * Layout exactly matches COBOL picture clauses.
     */
    private String formatDetailLine(TaxResult r) {
        // DTL-ID (PIC 9(05)) – zero-filled, 5 chars
        String id     = String.format("%05d", r.getEmpId());
        // DTL-NAME (PIC X(20)) – left-justified, space-padded to 20
        String name   = padRight(r.getEmpName(), 20);
        // DTL-GROSS / DTL-TAX / DTL-NET (Z,ZZZ,ZZ9.99) – right-justified, 11 chars
        String gross  = padLeft(MONEY_FMT.format(r.getGrossPay()), 11);
        String tax    = padLeft(MONEY_FMT.format(r.getTaxAmount()), 11);
        String net    = padLeft(MONEY_FMT.format(r.getNetPay()), 11);
        // DTL-RATE (Z9.9) – right-justified, 4 chars
        String rate   = padLeft(RATE_FMT.format(r.getEffRate()), 4);

        // Assemble: id(5) + sp(2) + name(20) + sp(1) + gross(11) +
        //           sp(2) + tax(11) + sp(2) + net(11) + sp(2) + rate(4) = 71 chars → pad to 80
        String line = id + "  " + name + " " + gross + "  " + tax + "  " + net + "  " + rate;
        return padRight(line, 80);
    }

    /**
     * Formats TRL-LINE (80 chars).
     * FILLER PIC X(42) = "TOTAL TAX WITHHELD:" (right-padded)
     * TRL-TAX  ZZZ,ZZZ,ZZ9.99 → 14 chars
     */
    private String formatTrailerLine(BigDecimal totalTax) {
        String total = padLeft(TOTAL_FMT.format(totalTax), 14);
        return padRight(TOTAL_LABEL + total, 80);
    }

    private void writeLine(BufferedWriter writer, String line) throws IOException {
        writer.write(line);
        writer.newLine();
    }

    private static String padRight(String s, int width) {
        if (s == null) s = "";
        if (s.length() >= width) return s.substring(0, width);
        return s + " ".repeat(width - s.length());
    }

    private static String padLeft(String s, int width) {
        if (s == null) s = "";
        if (s.length() >= width) return s.substring(0, width);
        return " ".repeat(width - s.length()) + s;
    }
}

