package com.example.taxcalc.runner;

import com.example.taxcalc.domain.Employee;
import com.example.taxcalc.domain.TaxResult;
import com.example.taxcalc.repository.EmployeeRepository;
import com.example.taxcalc.repository.TaxResultRepository;
import com.example.taxcalc.service.ReportService;
import com.example.taxcalc.service.TaxCalculationService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/**
 * Orchestrates the full TAXCALC batch job.
 *
 * Equivalent to MAIN-PARA in TAXCALC.cbl:
 *   1. Open "EMP-FILE" → fetch all employees from PostgreSQL
 *   2. For each employee perform CALC-TAX (via TaxCalculationService)
 *   3. Accumulate WS-TOTAL-TAX (ADD WS-TAX TO WS-TOTAL-TAX)
 *   4. Persist all TaxResult rows (idempotent per run_id)
 *   5. Write the flat-file tax report (via ReportService)
 *   6. DISPLAY "TAXCALC: TAX REPORT WRITTEN"
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class TaxCalcRunner implements ApplicationRunner {

    private final EmployeeRepository      employeeRepository;
    private final TaxResultRepository     taxResultRepository;
    private final TaxCalculationService   taxCalculationService;
    private final ReportService           reportService;

    @Override
    @Transactional
    public void run(ApplicationArguments args) throws Exception {
        UUID runId = UUID.randomUUID();
        log.info("TAXCALC batch started – runId={}", runId);

        // ── OPEN INPUT EMP-FILE ─────────────────────────────────────────
        // Equivalent: fetch all employees ordered by emp_id (preserves
        // file-sequential read order from employees.dat)
        List<Employee> employees = employeeRepository.findAll(
                org.springframework.data.domain.Sort.by("empId"));

        if (employees.isEmpty()) {
            log.warn("No employee records found – report will be empty.");
        }

        // ── PERFORM UNTIL END-OF-FILE ───────────────────────────────────
        // WS-TOTAL-TAX  PIC 9(09)V99 VALUE 0
        BigDecimal wsTotalTax = BigDecimal.ZERO;
        List<TaxResult> results = new ArrayList<>(employees.size());

        for (Employee emp : employees) {
            // PERFORM CALC-TAX
            TaxResult result = taxCalculationService.calculate(emp, runId);

            // ADD WS-TAX TO WS-TOTAL-TAX
            wsTotalTax = wsTotalTax.add(result.getTaxAmount());

            results.add(result);
        }

        // ── Persist results (repository pattern replaces WRITE RPT-LINE) ─
        taxResultRepository.saveAll(results);

        // ── WRITE flat-file report ──────────────────────────────────────
        reportService.writeReport(results, wsTotalTax);

        // ── DISPLAY "TAXCALC: TAX REPORT WRITTEN" ───────────────────────
        log.info("TAXCALC: TAX REPORT WRITTEN – employees={} totalTax={} runId={}",
                 results.size(), wsTotalTax, runId);
    }
}

