package com.example.taxcalc.service;

import com.example.taxcalc.domain.Employee;
import com.example.taxcalc.domain.TaxResult;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

import java.math.BigDecimal;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Verifies every branch of the progressive tax bracket logic
 * (mirrors the COBOL EVALUATE TRUE cases in CALC-TAX).
 */
class TaxCalculationServiceTest {

    private TaxCalculationService service;

    @BeforeEach
    void setUp() {
        service = new TaxCalculationService();
    }

    @ParameterizedTest(name = "salary={0} expectedTax={1} expectedNet={2} expectedRate={3}")
    @CsvSource({
        // Bracket 1: 0% – 0 to 30,000
        "0.00,       0.00,       0.00,      0.0",
        "15000.00,   0.00,   15000.00,      0.0",
        "30000.00,   0.00,   30000.00,      0.0",
        // Bracket 2: 10% on excess over 30,000
        "30001.00,   0.10,   30000.90,      0.0",
        "45000.00,   1500.00, 43500.00,     3.3",
        "60000.00,   3000.00, 57000.00,     5.0",
        // Bracket 3: 3,000 + 20% on excess over 60,000
        "60001.00,   3000.20, 57000.80,     5.0",
        "75000.00,   6000.00, 69000.00,     8.0",
        "90000.00,   9000.00, 81000.00,    10.0",
        // Bracket 4: 9,000 + 30% on excess over 90,000
        "90001.00,   9000.30, 81000.70,    10.0",
        "120000.00, 18000.00,102000.00,    15.0",
        "200000.00, 42000.00,158000.00,    21.0"
    })
    @DisplayName("CALC-TAX bracket logic")
    void testTaxBrackets(String salary, String expectedTax, String expectedNet, String expectedRate) {
        Employee emp = new Employee(1, "TEST EMPLOYEE", new BigDecimal(salary));
        TaxResult result = service.calculate(emp, UUID.randomUUID());

        assertThat(result.getTaxAmount())
                .as("taxAmount for salary=%s", salary)
                .isEqualByComparingTo(new BigDecimal(expectedTax));

        assertThat(result.getNetPay())
                .as("netPay for salary=%s", salary)
                .isEqualByComparingTo(new BigDecimal(expectedNet));

        assertThat(result.getEffRate())
                .as("effRate for salary=%s", salary)
                .isEqualByComparingTo(new BigDecimal(expectedRate));
    }
